  SWIG_Python_SetConstant(d, "Hep3Vector_Y",SWIG_From_int(static_cast< int >(CLHEP::Hep3Vector::Y)));
  SWIG_Python_SetConstant(d, "Hep3Vector_Z",SWIG_From_int(static_cast< int >(CLHEP::Hep3Vector::Z)));
  SWIG_Python_SetConstant(d, "Hep3Vector_NUM_COORDINATES",SWIG_From_int(static_cast< int >(CLHEP::Hep3Vector::NUM_COORDINATES)));
  SWIG_Python_SetConstant(d, "Hep3Vector_SIZE",SWIG_From_int(static_cast< int >(CLHEP::Hep3Vector::SIZE)));
